    @Test
    @DisplayName("当排序开启时，应根据Menu的sort字段对所有子级进行升序排序")
    void processElement_whenSortIsEnabled_shouldSortByMenuSortField() {
        // 如果构造函数未修改，但可以设置 Comparator
        TreeNodeOpe<TreeNodeExpand<MenuDo>, ElementTreeExpand<MenuDo>> treeNodeOpe =
                new TreeNodeOpeExpand<>(originalMenuRootList, originalMenuChildList);
        treeNodeOpe.setAscending(true); // 确保是升序
        treeNodeOpe.setSortEnable(true);
        // --- 执行 ---
        final List<ElementTreeExpand<MenuDo>> resultTree = treeNodeOpe.processElement();
        // --- 验证 ---
        assertNotNull(resultTree);
        assertEquals(2, resultTree.size(), "根节点数量应为2");
        // 验证根节点的顺序: "平台管理"(sort:2) 和 "首页"(sort:2)，顺序可能不变或按ID排，我们验证内容即可
        ElementTreeExpand<MenuDo> platformManagement = findElementById(resultTree, "1718332765759647744");
        assertNotNull(platformManagement, "应能找到'平台管理'");
        // 验证 "平台管理" 的子节点是否按 sort 字段排序:
        // 菜单管理(3) -> 授权管理(4) -> 字典管理(18)
        List<ElementTreeExpand<MenuDo>> platformChildren = platformManagement.getChildren();
        assertNotNull(platformChildren);
        List<String> actualPlatformChildrenLabels = platformChildren.stream()
                .map(ElementTreeExpand::getLabel).collect(Collectors.toList());
        List<String> expectedPlatformChildrenLabels = List.of("菜单管理", "授权管理", "字典管理");
        assertEquals(expectedPlatformChildrenLabels, actualPlatformChildrenLabels, "'平台管理'的子节点未按sort字段排序");
        // 验证更深层次的 "授权管理" 的子节点排序:
        // 账号列表(6) -> 岗位列表(7)
        ElementTreeExpand<MenuDo> authorizationManagement = findElementById(platformChildren, "1722057197739094016");
        assertNotNull(authorizationManagement);
        List<ElementTreeExpand<MenuDo>> authChildren = authorizationManagement.getChildren();
        assertNotNull(authChildren);
        List<String> actualAuthChildrenLabels = authChildren.stream()
                .map(ElementTreeExpand::getLabel).collect(Collectors.toList());
        List<String> expectedAuthChildrenLabels = List.of("账号列表", "岗位列表");
        assertEquals(expectedAuthChildrenLabels, actualAuthChildrenLabels, "'授权管理'的子节点未按sort字段排序");
    }


