    /**
     * 辅助方法，用于根据ID在 ElementTreeExpand 节点列表中查找节点。
     * @param nodes 要搜索的节点列表
     * @param id    要查找的ID
     * @return 找到的节点，如果未找到则返回 null
     */
    private ElementTreeExpand<String> findElementByIdStr(List<ElementTreeExpand<String>> nodes, String id) {
        if (nodes == null || id == null) {
            return null;
        }
        return nodes.stream()
                .filter(node -> id.equals(node.getId()))
                .findFirst()
                .orElse(null);
    }

    /**
     * 辅助方法，用于在 ElementTreeExpand 列表中查找节点
     */
    private ElementTreeExpand<MenuDo> findElementById(List<ElementTreeExpand<MenuDo>> nodes, String id) {
        if (nodes == null || id == null) return null;
        for (ElementTreeExpand<MenuDo> node : nodes) {
            if (id.equals(node.getId())) {
                return node;
            }
        }
        return null;
    }

    /**
     * 辅助方法，用于根据ID在节点列表中查找节点。
     *
     * @param nodes 要搜索的节点列表
     * @param id    要查找的ID
     * @return 找到的节点，如果未找到则返回 null
     */
    private TreeNodeExpand<String> findNodeById(List<TreeNodeExpand<String>> nodes, String id) {
        if (nodes == null || id == null) {
            return null;
        }
        return nodes.stream()
                .filter(node -> id.equals(node.getId()))
                .findFirst()
                .orElse(null);
    }
